// Read-only native Q1 inspection. This is the existing declared friend name;
// it constructs a separate LinearForm and never changes native state or fields.
namespace raikou::mfem_backend {class PicReactionBatch {public:
 static std::vector<double> nodal(GapPic& pic,const std::vector<GapParticle>& particles){mfem::LinearForm rhs(&pic.space_);rhs=0;mfem::Array<int>dofs;mfem::Vector shape;for(const auto& p:particles){mfem::IntegrationPoint point;const int element=pic.locate(p.position_m[0],p.position_m[1],point);const auto* fe=pic.space_.GetFE(element);shape.SetSize(fe->GetDof());fe->CalcShape(point,shape);pic.space_.GetElementDofs(element,dofs);const double q=p.charge_C*p.weight/pic.options_.depth_m;rhs.AddElementVector(dofs,shape*=q);}std::vector<double> out(rhs.Size());for(int i=0;i<rhs.Size();++i)out[i]=rhs[i]*pic.options_.depth_m;return out;}
};}
constexpr double qe=1.602176634e-19,me=9.1093837139e-31,c=299792458.,amu=1.66053906660e-27;
const double M=18.01056468403*amu,H=1.00782503223*amu;
m::GapPicOptions options(){m::GapPicOptions o;o.nx=o.ny=45;o.width_m=o.gap_m=.009;o.depth_m=.025;o.finite_foils=true;o.finite_axial_extent=true;o.short_z_m=0;o.feed_z_m=.025;o.lower_foil={.002,.007,.0018,.002};o.upper_foil={.002,.007,.007,.0072};return o;}
struct Sample {std::string model,channel;double E=0;bool capture=false;std::vector<std::string> states;std::vector<k::CollisionMomentum> momentum;std::vector<double> masses;double sigma=0;int level=-1;};
std::vector<m::ArenaStateSpec> catalog(const k::StrictCollisionDataset& data){auto b=k::conditional_water_mass_basis(data,M,H);std::vector<m::ArenaStateSpec>s{{"electron",0,0,-1,me,0,0},{"H2O",2,1,0,M,0,0},{"H_1s",1,0,0,H,0,0},{"Hm",1,0,-1,b.Hminus_kg,0,-.75*qe},{"OHm_X_v0",1,1,-1,b.OHminus_X_v0_kg,0,3.27*qe},{"H2Op_ground",2,1,1,b.H2Oplus_kg,0,12.621*qe}};for(int v=0;v<5;++v){double internal=k::hminus_Ram65_vibrational_eV(data,v)*qe;s.push_back({"OH_X_v"+std::to_string(v),1,1,0,b.OH_X_v0_kg+internal/(c*c),internal,5.1*qe});}const auto& I=data.metadata().at("outer3_fragment_ionization_eV");double ih=I.at("H").get<double>()*qe,ioh=I.at("OH").get<double>()*qe;s.push_back({"Hp",1,0,1,H-me+ih/(c*c),0,ih});s.push_back({"OHp_X_ground",1,1,1,b.OH_X_v0_kg-me+ioh/(c*c),0,5.1*qe+ioh});return s;}
std::vector<Sample> samples(const k::StrictCollisionDataset& data){std::vector<Sample> out;const auto b=k::conditional_water_mass_basis(data,M,H);const k::CollisionMomentum beam{.6,0,.8};
 {auto p=k::conditional_h2o_parent_products(data,"parent_ground_equal_pair_CM_v1",100,1,M,beam,{0,1,0});out.push_back({"parent_ground_equal_pair_CM_v1","H2O:ion_yield:H2O+",100,false,{"electron","electron","H2Op_ground"},{p.primary_momentum_kg_m_s,p.secondary_momentum_kg_m_s,p.ion_momentum_kg_m_s},{me,me,p.ion_mass_kg},p.cross_section_m2,-1});}
 auto weights=data.kernel_status("H2O:attachment_yield:Hminus","Hminus_Ram65_factorized_window_v1").at("model").at("OH_vibrational_relative_intensities").get<std::vector<double>>();double sum=0,prefix=0;for(auto x:weights)sum+=x;for(int v=0;v<5;++v){const double u=(prefix+.5*weights[v])/sum;prefix+=weights[v];auto p=k::conditional_hminus_Ram65_products(data,"Hminus_Ram65_factorized_window_v1",6.5,1,M,b.Hminus_kg,beam,u,.37,.61);if(p.OH_vibrational_level!=v)throw std::runtime_error("selected level fixture");out.push_back({"Hminus_Ram65_factorized_window_v1","H2O:attachment_yield:Hminus",6.5,true,{"Hm","OH_X_v"+std::to_string(v)},{p.Hminus_momentum_kg_m_s,p.OH_momentum_kg_m_s},{b.Hminus_kg,p.OH_state_mass_kg},p.cross_section_m2,v});}
 {auto p=k::conditional_ohminus_ground_products(data,"OHminus_ground_isotropic_CM_v1",6.5,1,M,H,beam,{0,1,0});out.push_back({"OHminus_ground_isotropic_CM_v1","H2O:attachment_yield:OHminus",6.5,true,{"OHm_X_v0","H_1s"},{p.anion_momentum_kg_m_s,p.neutral_momentum_kg_m_s},{p.anion_state_mass_kg,p.neutral_state_mass_kg},p.cross_section_m2,-1});}
 {auto p=k::conditional_A1B1_dissociation_products(data,"A1B1_fixed_loss_dipole_ground_v1",20,1,M,H,beam,.42,.31,{0,-1,0});out.push_back({"A1B1_fixed_loss_dipole_ground_v1","H2O:electronic_A1B1",20,false,{"electron","H_1s","OH_X_v0"},{p.electron_momentum_kg_m_s,p.H_momentum_kg_m_s,p.OH_momentum_kg_m_s},{me,H,p.OH_state_mass_kg},p.cross_section_m2,-1});}
 for(const auto& model:{"outer3_BEB_Tan_parent_v1","outer3_BEB_Tan_OHp_H_v1","outer3_BEB_Tan_Hp_OH_v1"}){auto p=k::conditional_outer3_ionization_products(data,model,8084.470604111418,1,M,H,beam,{0,1,0},{1,0,0});Sample s;s.model=model;s.channel=std::string("H2O:conditional_outer3:")+(std::string(model)=="outer3_BEB_Tan_parent_v1"?"parent":std::string(model)=="outer3_BEB_Tan_OHp_H_v1"?"OHp_H":"Hp_OH");s.E=8084.470604111418;s.sigma=p.cross_section_m2;for(int i=0;i<p.product_count;++i){s.states.push_back(p.state_id[i]=="e_g"?"electron":p.state_id[i]);s.momentum.push_back(p.momentum_kg_m_s[i]);s.masses.push_back(p.mass_kg[i]);}out.push_back(s);}
 return out;}
J record_population(m::PicArena& a){J rows=J::array();for(const auto& [id,p]:a.snapshot()->packets)rows.push_back({{"id",id},{"state",p.state},{"count",{p.count.hi,p.count.lo}}});return rows;}
int main(int argc,char** argv){try{
 if(argc!=4)return 2;
 const auto data=k::StrictCollisionDataset::read(argv[1]);const J bindings=[](const char* path){J j;std::ifstream f(path);f>>j;if(!f)throw std::runtime_error("binding read");return j;}(argv[2]);const std::string out=argv[3];const std::string dataset=bindings.at("dataset_sha256"),kernel=bindings.at("kernel_manifest_sha256"),file=bindings.at("kernel_binding_file_sha256");auto specs=catalog(data);std::map<std::string,m::ArenaStateSpec> bystate;for(auto s:specs)bystate.emplace(s.id,s);auto all=samples(data);J records=J::array();
 auto run=[&](const Sample& sample,int placement,double ew,double nw,bool wrong_product_contract){m::GapPic pic(options());const double x=sample.E*qe/(me*c*c),u=c*std::sqrt(x*(x+2));m::GapParticle e,n;e.position_m={.004,.004,.0125};e.proper_velocity_m_s={.6*u,0,.8*u};e.mass_kg=me;e.weight=ew;n.position_m=placement==0?e.position_m:placement==1?m::PicVector{.00403,.004,.0125}:m::PicVector{.004,.004,.0135};n.proper_velocity_m_s={0,0,0};n.mass_kg=M;n.charge_C=0;n.weight=nw;const auto ids=pic.add_authored_batch({e,n});pic.solve_fields();auto product_states=sample.states;if(wrong_product_contract)product_states[1]="OH_X_v0";m::ArenaChannel channel{sample.channel,"electron","H2O",product_states,dataset,kernel,file,sample.model};m::PicArena arena(pic,specs,{channel},{{"primary","electron","forced-v5-fixture","",{ew,0},{ids[0]}},{"water","H2O","forced-v5-fixture","",{nw,0},{ids[1]}}},"generic-v5-native-fixture");const auto before=arena.state_prefix();const auto native_before=m::PicArena::fingerprint(pic);const auto charge_before=m::PicReactionBatch::nodal(pic,pic.particles());const auto before_population=record_population(arena);const double W=std::min(ew,nw);
  m::ArenaEvent event;event.id="forced/v5/"+sample.model+"/"+std::to_string(sample.level);event.channel=sample.channel;event.primary="primary";event.target="water";event.event_weight=W;if(!sample.capture)event.scattered_primary_id="primary";if(ew>W)event.untouched_primary_id="primary/remainder";event.phase.state_prefix=before;event.phase.mesh_prefix=bindings.at("mesh_sha256");event.phase.clock_prefix=bindings.at("clock_sha256");event.provenance={m::ArenaProvenance::Kind::ConditionalPhysicalData,dataset,kernel,file,sample.model,"forced_kernel_integration_only",before,0};
  std::vector<m::GapParticle> incoming{e,n},proposed;incoming[0].weight=incoming[1].weight=W;double mass_max_relative=0;std::uint64_t max_ulp=0;for(std::size_t i=0;i<sample.states.size();++i){const auto& state=bystate.at(sample.states[i]);m::PicVector velocity{};for(int d=0;d<3;++d)velocity[d]=sample.momentum[i][d]/state.mass_kg;const bool primary=!sample.capture&&i==0;event.products.push_back({primary?"primary":"product/"+std::to_string(i),sample.states[i],velocity,primary?m::ArenaProduct::At::Primary:m::ArenaProduct::At::Target});m::GapParticle p=primary?e:n;p.proper_velocity_m_s=velocity;p.mass_kg=state.mass_kg;p.charge_C=state.charge_e*qe;p.weight=W;proposed.push_back(p);mass_max_relative=std::max(mass_max_relative,std::abs(sample.masses[i]-state.mass_kg)/state.mass_kg);const auto a=std::bit_cast<std::uint64_t>(sample.masses[i]),b=std::bit_cast<std::uint64_t>(state.mass_kg);max_ulp=std::max(max_ulp,a>b?a-b:b-a);}
  const auto qin=m::PicReactionBatch::nodal(pic,incoming),qout=m::PicReactionBatch::nodal(pic,proposed);double attempted=0;long double sum=0;for(std::size_t i=0;i<qin.size();++i){const double d=qout[i]-qin[i];attempted=std::max(attempted,std::abs(d));sum+=d;}
  J row={{"model",sample.model},{"channel",sample.channel},{"OH_level",sample.level},{"energy_eV",sample.E},{"cross_section_m2",sample.sigma},{"capture",sample.capture},{"placement",placement},{"electron_weight",ew},{"water_weight",nw},{"event_weight",W},{"wrong_product_contract",wrong_product_contract},{"kernel_catalog_mass_max_relative",mass_max_relative},{"kernel_catalog_mass_max_ULP",max_ulp},{"before_population",before_population},{"attempted_cohort_node_delta_Linf_C",attempted},{"attempted_cohort_node_delta_sum_C",double(sum)}};
  try{auto token=arena.prepare(event);if(arena.state_prefix()!=before||m::PicArena::fingerprint(pic)!=native_before)throw std::runtime_error("prepare mutation");if(!arena.try_publish(token))throw std::runtime_error("publish");row["accepted"]=true;row["audit"]=token.audit();row["after_population"]=record_population(arena);const auto q=m::PicReactionBatch::nodal(pic,pic.particles());double delta=0;for(std::size_t i=0;i<q.size();++i)delta=std::max(delta,std::abs(q[i]-charge_before[i]));row["accepted_native_node_delta_Linf_C"]=delta;row["horizontal_transfers_zero"]=std::all_of(pic.horizontal_transfers_C().begin(),pic.horizontal_transfers_C().end(),[](double x){return x==0;});row["vertical_transfers_zero"]=std::all_of(pic.vertical_transfers_C().begin(),pic.vertical_transfers_C().end(),[](double x){return x==0;});if(sample.capture&&placement==0&&ew==2){const auto path=out+"/captured-primary.json";arena.save(path);m::GapPic fresh(options());auto restored=m::PicArena::restore(fresh,path,specs,{channel},"generic-v5-native-fixture");row["capture_restart_population_exact"]=record_population(*restored)==record_population(arena);}if(!arena.try_rollback(token)||arena.state_prefix()!=before||m::PicArena::fingerprint(pic)!=native_before)throw std::runtime_error("rollback");row["rollback_exact"]=true;}catch(const std::exception& error){row["accepted"]=false;row["refusal"]=error.what();row["refusal_unchanged"]=arena.state_prefix()==before&&m::PicArena::fingerprint(pic)==native_before;}records.push_back(row);
 };
 for(const auto& s:all)run(s,s.capture?0:1,1,1,false);
 run(all[1],0,2,1,false);run(all[6],0,.25,1,false);run(all[1],1,1,1,false);run(all[6],1,1,1,false);run(all[1],2,1,1,false);run(all[2],0,1,1,true);
 auto rates=k::conditional_outer3_ionization_rates(data,8084.470604111418);J cat=J::array();for(auto s:specs)cat.push_back({{"id",s.id},{"H",s.hydrogen},{"O",s.oxygen},{"q_e",s.charge_e},{"mass_kg",s.mass_kg},{"internal_J",s.internal_J},{"reference_J",s.reference_J}});std::ofstream f(out+"/probes.json");f<<J{{"catalog",cat},{"records",records},{"unmapped_2a1_m2",rates.unmapped_2a1_m2},{"mapped_four_valence_fraction",rates.mapped_subset_m2()/rates.four_valence_total_m2},{"target_rest_lab_frame_coincides",true},{"physical_time_advanced",false}}.dump(2)<<'\n';if(!f)return 3;std::cout<<records.size()<<" actual v5 product/native admission records\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
